contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address[] memory tos, uint v) public payable {
        require(tos.length == 1);
        require(v < 2**128);
        bool reverted;
        bool ok;
        try c.transfer(from, address(this), tos, v) returns (bool r) {
            reverted = false;
            ok = r;
        } catch {
            reverted = true;
        }
        assert(!reverted && ok == true);
    }
    fallback() external payable {}
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address[] memory _tos, uint v) public {
        require(_tos.length > 0);
        // act as a token that reverts on every transferFrom
        bool reverted;
        try c.transfer(from, address(this), _tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);
    }

    fallback(bytes calldata data) external payable returns (bytes memory) {
        if (data.length >= 4 && bytes4(data) == bytes4(keccak256("transferFrom(address,address,uint256)"))) {
            revert();
        }
        return "";
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Plain address with no code: low-level calls to it succeed, so the
    // inner calls in C.transfer report success and the loop completes.
    function run(address from, address[] memory tos, uint v) public {
        require(tos.length > 0);
        // caddress = address(this); this test contract accepts the low-level
        // calls via its fallback below.
        bool r = c.transfer(from, address(this), tos, v);
        assert(r == true);
    }

    fallback() external {}
    receive() external payable {}
}

