contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address token, address to, uint v) public payable {
        require(address(this).balance >= 0);
        address[] memory empty = new address[](0);
        bool revertedEmpty;
        try c.transfer(from, token, empty, v) { revertedEmpty = false; } catch { revertedEmpty = true; }
        address[] memory one = new address[](1);
        one[0] = to;
        bool ok;
        bool revertedNonEmpty;
        try c.transfer(from, token, one, v) returns (bool r) { revertedNonEmpty = false; ok = r; } catch { revertedNonEmpty = true; ok = false; }
        assert(revertedEmpty && (revertedNonEmpty || ok));
    }
    receive() external payable {}
}
